import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

/** Storage seam for uploaded image files. */
export interface ImageStore {
  /** Directory the images are served from, under the image URL path. */
  readonly directory: string;
  /** Saves the bytes under the given file name. The name is generated by the server, never by the user. */
  save(fileName: string, bytes: Buffer): void;
}

export function createFileImageStore(directory: string): ImageStore {
  const resolved = path.resolve(directory);
  mkdirSync(resolved, { recursive: true });
  return {
    directory: resolved,
    save: (fileName, bytes) => {
      writeFileSync(path.join(resolved, path.basename(fileName)), bytes);
    },
  };
}

export function createInMemoryImageStore(directory = "memory"): ImageStore & { files: Map<string, Buffer> } {
  const files = new Map<string, Buffer>();
  return { directory, files, save: (fileName, bytes) => void files.set(fileName, bytes) };
}
